(7306956, 1140274, 177322, '<td valign="top">Crystal-like clarity.  Two strong diagonals "x" this square boldly and subtly: The obvious silvery edge is the most dominating diagonal but that crimson light powering its way through the middle of the maroon and yellow lighting is an equally dynamic diagonal.  The change of texture from the velvety upper left to the nubbly lower right is an interesting study in of itself.  In the thumbnail this appears overly simple; in reality it is quite complex and a most engaging study. Good luck.</td>', 'Crystal-like clarity.  Two strong diagonals "x" this square boldly and subtly: The obvious silvery edge is the most dominating diagonal but that crimson light powering its way through the middle of the maroon and yellow lighting is an equally dynamic diagonal.  The change of texture from the velvety upper left to the nubbly lower right is an interesting study in of itself.  In the thumbnail this appears overly simple; in reality it is quite complex and a most engaging study. Good luck.', '2015-01-26 16:35:22.000000', NULL, 1),
(7306960, 1140160, 177322, '<td valign="top">Yummy, yummy.  That there are circles upon circles repeated within the square is playful.  For me, the heavy border overpowers the gaiety of the subject and effectively obliterates what could be one more circle, the serving tray. Nonetheless, a enjoyable image.</td>', 'Yummy, yummy.  That there are circles upon circles repeated within the square is playful.  For me, the heavy border overpowers the gaiety of the subject and effectively obliterates what could be one more circle, the serving tray. Nonetheless, a enjoyable image.', '2015-01-26 16:44:12.000000', NULL, 1),
(7306962, 1140124, 177322, '<td valign="top">Sharp focus on the subject with his colors nicely repeated in the perch and upper right corner.  {Reminds me I need to get another quart of mealworms!}</td>', 'Sharp focus on the subject with his colors nicely repeated in the perch and upper right corner.  {Reminds me I need to get another quart of mealworms!}', '2015-01-26 16:48:28.000000', NULL, 1),
(7307005, 1139970, 1792, '<td valign="top">This has no subject or focal point  wouldn''t really matter how you cropped it.</td>', 'This has no subject or focal point  wouldn''t really matter how you cropped it.', '2015-01-26 19:46:09.000000', NULL, 1),
(7307006, 1140321, 1792, '<td valign="top">Nice light.</td>', 'Nice light.', '2015-01-26 19:47:57.000000', NULL, 1),
