(7307017, 1140225, 16046, '<td valign="top">Best in show award, congrats</td>', 'Best in show award, congrats', '2015-01-26 20:46:31.000000', NULL, 1),
(7307029, 1140336, 83313, '<td valign="top">...but sold out of bras and panties.</td>', '...but sold out of bras and panties.', '2015-01-26 21:39:31.000000', NULL, 1),
(7307030, 1140231, 83313, '<td valign="top">I don''t have a folder yet. I need a folder.</td>', 'I don''t have a folder yet. I need a folder.', '2015-01-26 21:40:17.000000', NULL, 1),
(7307043, 1140344, 86447, '<td valign="top">I think that... for the Square Crop to be "meaningful" that... the image has to fill the whole of the square and be gorgeous... or filled with emotion.<br/> <br/>Yep.  This fits all of that.<br/> <br/>Lovely.<br/> <br/>Indeed... lovely.</td>', 'I think that... for the Square Crop to be "meaningful" that... the image has to fill the whole of the square and be gorgeous... or filled with emotion. Yep.  This fits all of that. Lovely. Indeed... lovely.', '2015-01-26 22:00:38.000000', NULL, 1),
(7307049, 1140215, 177322, '<td valign="top">Shapes come forward here:  the brownie square within the square crop is well centered.  The dollop of ice cream is a nicely centered circle. Since ''centeredness'' is surely something one can take advantage of in a square crop, I laud your accomplishment with that.  The swirls of the serving dish frame the food energetically.  It does seem a tad OOF - food is so dang hard to shoot - but overall, it is an image that offers the eye plenty to explore.</td>', 'Shapes come forward here:  the brownie square within the square crop is well centered.  The dollop of ice cream is a nicely centered circle. Since ''centeredness'' is surely something one can take advantage of in a square crop, I laud your accomplishment with that.  The swirls of the serving dish frame the food energetically.  It does seem a tad OOF - food is so dang hard to shoot - but overall, it is an image that offers the eye plenty to explore.', '2015-01-26 22:11:24.000000', NULL, 1),
(7307050, 1140262, 177322, '<td valign="top">I like how the lines zigzag through the image with the first zig being the gate and the final zag being the horizon. They hike you right through this lovely setting.</td>', 'I like how the lines zigzag through the image with the first zig being the gate and the final zag being the horizon. They hike you right through this lovely setting.', '2015-01-26 22:16:33.000000', NULL, 1),
(7307052, 1140331, 177322, '<td valign="top">Aren''t milkweeds the most fascinating plants to shoot?  Nice dof.</td>', 'Aren''t milkweeds the most fascinating plants to shoot?  Nice dof.', '2015-01-26 22:18:27.000000', NULL, 1),
(7307062, 1140354, 177322, '<td valign="top">Spot on sharp.  His concentration on the bathing ritual made me chuckle. Good luck.</td>', 'Spot on sharp.  His concentration on the bathing ritual made me chuckle. Good luck.', '2015-01-26 22:33:37.000000', NULL, 1),
(7307064, 1140183, 177322, '<td valign="top">The loss of the model''s face in her hair is somewhat disappointing and her foot seems rotated contrary to her torso - perhaps due to the twirl.  Otherwise this is quite a fanciful setting. It must have been challenging to shoot. Good luck.</td>', 'The loss of the model''s face in her hair is somewhat disappointing and her foot seems rotated contrary to her torso - perhaps due to the twirl.  Otherwise this is quite a fanciful setting. It must have been challenging to shoot. Good luck.', '2015-01-26 22:38:22.000000', NULL, 1),
(7307083, 1140231, 114285, '<td valign="top">Love the texture.</td>', 'Love the texture.', '2015-01-27 00:42:08.000000', NULL, 1),
(7307086, 1140288, 108069, '<td valign="top">Nicely framed. Reminds me of the region in which I live. Shadow curl adds a nice twist.</td>', 'Nicely framed. Reminds me of the region in which I live. Shadow curl adds a nice twist.', '2015-01-27 01:17:00.000000', NULL, 1),
(7307087, 1140373, 114285, '<td valign="top">I just love your processing, a wonderful image af a happy girl, better than an angry sultry look anytime.<br/> <br/>I do however wish she was looking at the camera and that right hand top corner is bugging me not sure why, nevertheless one of the better ones for sure.</td>', 'I just love your processing, a wonderful image af a happy girl, better than an angry sultry look anytime. I do however wish she was looking at the camera and that right hand top corner is bugging me not sure why, nevertheless one of the better ones for sure.', '2015-01-27 01:31:06.000000', NULL, 1),
(7307101, 1140228, 163430, '<td valign="top">HA! I know this place. Munich. The BMW museum is behind the camera and this building is called BMW Welt, i think. The lights in the back are from the Olympiastadion (1972 summer Olympic games were held there) across the boulevard.</td>', 'HA! I know this place. Munich. The BMW museum is behind the camera and this building is called BMW Welt, i think. The lights in the back are from the Olympiastadion (1972 summer Olympic games were held there) across the boulevard.', '2015-01-27 05:32:34.000000', NULL, 1),
(7307153, 1140310, 98565, '<td valign="top">the diagonal works fine in a square picture. The flag is a little bit distracting for me</td>', 'the diagonal works fine in a square picture. The flag is a little bit distracting for me', '2015-01-27 11:27:04.000000', NULL, 1),
(7307154, 1140274, 98565, '<td valign="top">awesome colours!</td>', 'awesome colours!', '2015-01-27 11:28:05.000000', NULL, 1),
(7307156, 1140283, 98565, '<td valign="top">a very nice setting - works fine as a square</td>', 'a very nice setting - works fine as a square', '2015-01-27 11:29:07.000000', NULL, 1),
(7307157, 1139967, 98565, '<td valign="top">this is certainly a lovely lady but due to the heavy processing I''m missing the natural beauty</td>', 'this is certainly a lovely lady but due to the heavy processing I''m missing the natural beauty', '2015-01-27 11:30:18.000000', NULL, 1),
(7307194, 1140339, 98565, '<td valign="top">uuhh - makes me shiver -</td>', 'uuhh - makes me shiver -', '2015-01-27 14:06:06.000000', NULL, 1),
(7307197, 1140387, 98565, '<td valign="top">what a proud rooster<br/>I''d probably like it better when there was more visible texture in the feathers of its neck</td>', 'what a proud roosterI''d probably like it better when there was more visible texture in the feathers of its neck', '2015-01-27 14:18:00.000000', NULL, 1),
(7307199, 1140383, 98565, '<td valign="top">I like the idea with the rusty window. Somehow the lady is way to beautiful for this worn out surrounding ;-)</td>', 'I like the idea with the rusty window. Somehow the lady is way to beautiful for this worn out surrounding ;-)', '2015-01-27 14:23:20.000000', NULL, 1),
(7307202, 1140366, 98565, '<td valign="top">the view is guided quite elegantly here</td>', 'the view is guided quite elegantly here', '2015-01-27 14:24:45.000000', NULL, 1),
(7307204, 1140312, 98565, '<td valign="top">hmm, I wonder if the baboons would be more visible in the colour version of this picture... and I think it is less favorable that the two of them at the lower edge are half cropped</td>', 'hmm, I wonder if the baboons would be more visible in the colour version of this picture... and I think it is less favorable that the two of them at the lower edge are half cropped', '2015-01-27 14:27:12.000000', NULL, 1),
(7307231, 1140335, 98565, '<td valign="top">confusing straight lines combined with stars - I like it very much</td>', 'confusing straight lines combined with stars - I like it very much', '2015-01-27 16:21:20.000000', NULL, 1),
(7307232, 1140356, 98565, '<td valign="top">I like the complementary colours and the vintage style</td>', 'I like the complementary colours and the vintage style', '2015-01-27 16:23:30.000000', NULL, 1),
(7307236, 1140223, 98565, '<td valign="top">although those "models" aren''t what I''d call congenially  I have to admit that this picture is technically really well done. I hope for you that voters will take a look before they give low scores...</td>', 'although those "models" aren''t what I''d call congenially  I have to admit that this picture is technically really well done. I hope for you that voters will take a look before they give low scores...', '2015-01-27 16:43:23.000000', NULL, 1),
(7307314, 1140366, 177322, '<td valign="top">Quite frankly, initially I did not like this image, but it kept beckoning me back.  In the end, I think you''ve done well with the square crop by incorporating a very effective geometric design (the pathway) which, incidentally added the element of repetitive symmetry by virtue of the paving stone pattern.  The lamps add their own triangle to the square crop. B&amp;W was a good choice.  All in all, I''ve amended my initial sentiment and now consider it an image worth studying.  Nice work: 7.</td>', 'Quite frankly, initially I did not like this image, but it kept beckoning me back.  In the end, I think you''ve done well with the square crop by incorporating a very effective geometric design (the pathway) which, incidentally added the element of repetitive symmetry by virtue of the paving stone pattern.  The lamps add their own triangle to the square crop. B&W was a good choice.  All in all, I''ve amended my initial sentiment and now consider it an image worth studying.  Nice work: 7.', '2015-01-27 23:09:46.000000', NULL, 1),
(7307487, 1140222, 173844, '<td valign="top">Very powerful black and white.  The perfect perspective for this compact pose.  The arcs in the sidewalk grid offer a sweet stylistic counterpoint to the square framing.  Altogether excellent.</td>', 'Very powerful black and white.  The perfect perspective for this compact pose.  The arcs in the sidewalk grid offer a sweet stylistic counterpoint to the square framing.  Altogether excellent.', '2015-01-28 11:19:34.000000', NULL, 1),
(7307504, 1140342, 173844, '<td valign="top">Wonderful picture.  The square frame is subtly sectioned into perpendiculars set off by the man in the rolling wheelchair.  The lighting and golden tones bring out the rain that has recently passed.  His path seems long, lonely and sensually inviting.</td>', 'Wonderful picture.  The square frame is subtly sectioned into perpendiculars set off by the man in the rolling wheelchair.  The lighting and golden tones bring out the rain that has recently passed.  His path seems long, lonely and sensually inviting.', '2015-01-28 11:38:26.000000', NULL, 1),
(7307631, 1140347, 173844, '<td valign="top">A landscape that turns out to be a handsome black and white study that occupies a square frame with with aplomb.  Beautiful.  I love how the boulder seems to float above its surroundings.</td>', 'A landscape that turns out to be a handsome black and white study that occupies a square frame with with aplomb.  Beautiful.  I love how the boulder seems to float above its surroundings.', '2015-01-28 14:46:52.000000', NULL, 1),
(7307639, 1140251, 173844, '<td valign="top">Lovely work.  Looks like some sort of golden ratio operating here in this abstracted scene.  The square frame is pleasingly full with earthy tones.  Dapples its way onto the museum wall.</td>', 'Lovely work.  Looks like some sort of golden ratio operating here in this abstracted scene.  The square frame is pleasingly full with earthy tones.  Dapples its way onto the museum wall.', '2015-01-28 14:51:29.000000', NULL, 1),
(7307643, 1140299, 173844, '<td valign="top">Beautifully composed and colored still-life with an understated yet powerful presence.  The shapes and textures are simple, various and harmonious.  The way the stem carves the background is masterful.  The way the screen resembles a canvas is another telling touch.</td>', 'Beautifully composed and colored still-life with an understated yet powerful presence.  The shapes and textures are simple, various and harmonious.  The way the stem carves the background is masterful.  The way the screen resembles a canvas is another telling touch.', '2015-01-28 15:06:40.000000', NULL, 1),
(7307644, 1140267, 173844, '<td valign="top">Can''t see, in my opinion, this image not taking the blue ribbon.  It''s moody, challenging, fascinatingly lit, spacious, nicely tinted, scratchy and absolutely appropriate for a square shape.<br/>About this scratchiness, how is it achieved?  I like the deliberate scruffiness and visual dissonance it imparts.  My two favorite images in this challenge, this one and "it takes forever", utilize this effect.</td>', 'Can''t see, in my opinion, this image not taking the blue ribbon.  It''s moody, challenging, fascinatingly lit, spacious, nicely tinted, scratchy and absolutely appropriate for a square shape.About this scratchiness, how is it achieved?  I like the deliberate scruffiness and visual dissonance it imparts.  My two favorite images in this challenge, this one and "it takes forever", utilize this effect.', '2015-01-28 15:07:20.000000', NULL, 1),
(7307645, 1140158, 173844, '<td valign="top">Beautiful image in and of itself, but elevated to a more interesting level by the moody, scratchy processing.  It''s a filigree embedded in a dream.  Lovely, modulated blues.  A feeling poem.<br/>One of my two favorites in this challenge.</td>', 'Beautiful image in and of itself, but elevated to a more interesting level by the moody, scratchy processing.  It''s a filigree embedded in a dream.  Lovely, modulated blues.  A feeling poem.One of my two favorites in this challenge.', '2015-01-28 15:07:48.000000', NULL, 1),
(7307647, 1140048, 173844, '<td valign="top">That it looks like moonlight yet is overcast lends this image a spectral character.  Yes, the ripples are really nice.  And the bracketing vegetation provides visual anchor points.  Softly haunting.</td>', 'That it looks like moonlight yet is overcast lends this image a spectral character.  Yes, the ripples are really nice.  And the bracketing vegetation provides visual anchor points.  Softly haunting.', '2015-01-28 15:17:43.000000', NULL, 1),
(7307649, 1140257, 173844, '<td valign="top">A hot image that fills the frame to bursting.  Exciting and "brassy".</td>', 'A hot image that fills the frame to bursting.  Exciting and "brassy".', '2015-01-28 15:20:16.000000', NULL, 1),
(7307652, 1140274, 173844, '<td valign="top">The color tones and textures combine to make this an impressive study.</td>', 'The color tones and textures combine to make this an impressive study.', '2015-01-28 15:21:22.000000', NULL, 1),
(7307653, 1140329, 173844, '<td valign="top">A latter day raising of the flag at Iwo Jima, yet here it is a triumph of the spirit.  It easily holds its own in the central placement of the athletes.  Great picture.</td>', 'A latter day raising of the flag at Iwo Jima, yet here it is a triumph of the spirit.  It easily holds its own in the central placement of the athletes.  Great picture.', '2015-01-28 15:25:31.000000', NULL, 1),
(7307656, 1139939, 173844, '<td valign="top">Serene land/seascape that feels like a John Constable painting.  Quite beautiful.  The centralized horizon works, for me at least, because the mast and rigging stitch the halves together.</td>', 'Serene land/seascape that feels like a John Constable painting.  Quite beautiful.  The centralized horizon works, for me at least, because the mast and rigging stitch the halves together.', '2015-01-28 15:38:28.000000', NULL, 1),
(7307660, 1140225, 173844, '<td valign="top">Marvelous study of overwhelming depth.  Beautifully sits in the frame. It reminds one of the flower sermon.</td>', 'Marvelous study of overwhelming depth.  Beautifully sits in the frame. It reminds one of the flower sermon.', '2015-01-28 15:56:31.000000', NULL, 1),
(7307662, 1139967, 173844, '<td valign="top">Imaginatively handled intimate portrait that looks in part like a woodcut.  If not offered to us by the photographer, I''d almost feel like I were intruding.  Sensitive and charming.</td>', 'Imaginatively handled intimate portrait that looks in part like a woodcut.  If not offered to us by the photographer, I''d almost feel like I were intruding.  Sensitive and charming.', '2015-01-28 16:02:12.000000', NULL, 1),
(7307664, 1140228, 173844, '<td valign="top">Wonderfully stylized yet fully realistic sci-fi image with a great choice of perspective.  Uses the square frame quite well.</td>', 'Wonderfully stylized yet fully realistic sci-fi image with a great choice of perspective.  Uses the square frame quite well.', '2015-01-28 16:11:07.000000', NULL, 1),
(7307683, 1140363, 173844, '<td valign="top">Elegant portrait.</td>', 'Elegant portrait.', '2015-01-28 17:12:46.000000', NULL, 1),
(7307727, 1140215, 83149, '<td valign="top">Nice composition and subject, but it is very noisy and soft which really takes away from the image.</td>', 'Nice composition and subject, but it is very noisy and soft which really takes away from the image.', '2015-01-28 18:46:16.000000', NULL, 1),
(7307731, 1140328, 83149, '<td valign="top">The off center doesn''t work for me with the square crop.</td>', 'The off center doesn''t work for me with the square crop.', '2015-01-28 18:48:27.000000', NULL, 1),
(7307733, 1140312, 83149, '<td valign="top">Awkward crop on the bottom two.</td>', 'Awkward crop on the bottom two.', '2015-01-28 18:49:58.000000', NULL, 1),
(7307842, 1140288, 173844, '<td valign="top">I like this very much.  It''s well-composed.  The varied perpendiculars structure the image right into the square format; yet, there are some modest curves, also, to soften the effect (the wire, the reflected tree, the crook in the drain pipe).  Also, it plays with dimension.  It''s mainly two-dimensional, but then there are the modestly raised drainage pipes, wire and window frame.  The window itself busts loose by hinting at the inside beyond the coyly parted curtains and at the surrounding wide world suggested by the reflection of the rooftop and tree.  So much from apparently so little.</td>', 'I like this very much.  It''s well-composed.  The varied perpendiculars structure the image right into the square format; yet, there are some modest curves, also, to soften the effect (the wire, the reflected tree, the crook in the drain pipe).  Also, it plays with dimension.  It''s mainly two-dimensional, but then there are the modestly raised drainage pipes, wire and window frame.  The window itself busts loose by hinting at the inside beyond the coyly parted curtains and at the surrounding wide world suggested by the reflection of the rooftop and tree.  So much from apparently so little.', '2015-01-29 09:46:20.000000', NULL, 1),
(7307845, 1140146, 173844, '<td valign="top">Very pleasing rectilinear composition backed by a burst of filigree tree branches.  The building is a forced marriage of discordant textures, but there you have it --  no excuses, and it shakes one''s visual complacency.  I also like how the newly pointed portions of the stonework appear to be lit by patches of sunlight.</td>', 'Very pleasing rectilinear composition backed by a burst of filigree tree branches.  The building is a forced marriage of discordant textures, but there you have it --  no excuses, and it shakes one''s visual complacency.  I also like how the newly pointed portions of the stonework appear to be lit by patches of sunlight.', '2015-01-29 09:59:34.000000', NULL, 1),
(7307846, 1140373, 173844, '<td valign="top">Soft and sympathetic portrait of a beautiful woman.  It fills the frame perfectly.</td>', 'Soft and sympathetic portrait of a beautiful woman.  It fills the frame perfectly.', '2015-01-29 10:01:59.000000', NULL, 1),
(7307849, 1140333, 173844, '<td valign="top">Lovely and delicate image.  The colors are beautiful.  The lighting suggests that the structure is made of paper.  The heavily textured white paint on the door begs to be touched.  The dark bottom strip well serves the atmosphere of the scene.</td>', 'Lovely and delicate image.  The colors are beautiful.  The lighting suggests that the structure is made of paper.  The heavily textured white paint on the door begs to be touched.  The dark bottom strip well serves the atmosphere of the scene.', '2015-01-29 10:12:12.000000', NULL, 1),
(7307854, 1140208, 173844, '<td valign="top">Great subject for a square frame.  So welcoming.  There''s a feel of arrival after or during an adventure.  The snow and its texture is admirably displayed, seemingly lightly vignetted around the perimeter.  Artful.</td>', 'Great subject for a square frame.  So welcoming.  There''s a feel of arrival after or during an adventure.  The snow and its texture is admirably displayed, seemingly lightly vignetted around the perimeter.  Artful.', '2015-01-29 10:19:59.000000', NULL, 1),
(7307857, 1140403, 173844, '<td valign="top">Fine storybook-like illustration.  The lighting carries the day, bringing the scene to fruition.  Yet also, sorry, the vertical alignment of the heron and moon compel me to see the moon as, umm, a giant....</td>', 'Fine storybook-like illustration.  The lighting carries the day, bringing the scene to fruition.  Yet also, sorry, the vertical alignment of the heron and moon compel me to see the moon as, umm, a giant....', '2015-01-29 10:28:01.000000', NULL, 1),
(7307869, 1140341, 173844, '<td valign="top">Lovely thumbnail landscape with terrific depth.  The large rocks in the foreground enable the square format to work.  Wonderful tones.</td>', 'Lovely thumbnail landscape with terrific depth.  The large rocks in the foreground enable the square format to work.  Wonderful tones.', '2015-01-29 11:14:48.000000', NULL, 1),
(7307913, 1140027, 14867, '<td valign="top">Superb and rich pattern, it works like 9 beautiful little abstractions...but the lines should be *perfectly* vertical with such a subject!</td>', 'Superb and rich pattern, it works like 9 beautiful little abstractions...but the lines should be *perfectly* vertical with such a subject!', '2015-01-29 15:02:49.000000', NULL, 1),
(7307914, 1140215, 14867, '<td valign="top">Interesting and different. The focus / out of focus works perfectly here.</td>', 'Interesting and different. The focus / out of focus works perfectly here.', '2015-01-29 15:04:43.000000', NULL, 1),
