(7308598, 1140234, 37252, '<td valign="top">Very well done. Love the details, especially the reflection in the binocular glass</td>', 'Very well done. Love the details, especially the reflection in the binocular glass', '2015-01-31 21:16:48.000000', NULL, 1),
(7308599, 1140354, 37252, '<td valign="top">What a fun action shot. Love this</td>', 'What a fun action shot. Love this', '2015-01-31 21:17:47.000000', NULL, 1),
