(7308601, 1140196, 37252, '<td valign="top">Wish this was a bit sharper. Nice find though.</td>', 'Wish this was a bit sharper. Nice find though.', '2015-01-31 21:19:57.000000', NULL, 1),
(7308602, 1140251, 37252, '<td valign="top">I''ve never been a big fan of abstracts, but this one I find very intriguing. I would hang this one on my wall. Nicely done.</td>', 'I''ve never been a big fan of abstracts, but this one I find very intriguing. I would hang this one on my wall. Nicely done.', '2015-01-31 21:22:12.000000', NULL, 1),
(7308603, 1140216, 37252, '<td valign="top">nice candid capture</td>', 'nice candid capture', '2015-01-31 21:22:29.000000', NULL, 1),
(7308604, 1140383, 37252, '<td valign="top">Mixed emotions here. I sorta want her to be looking down in thought as he is, but then her looking at the camera and him at her really does say "mixed emotions"</td>', 'Mixed emotions here. I sorta want her to be looking down in thought as he is, but then her looking at the camera and him at her really does say "mixed emotions"', '2015-01-31 21:23:32.000000', NULL, 1),
(7308605, 1140158, 37252, '<td valign="top">This is nicely done with the overlay. Not always a fan of them, but it works very well here.</td>', 'This is nicely done with the overlay. Not always a fan of them, but it works very well here.', '2015-01-31 21:24:15.000000', NULL, 1),
(7308606, 1139939, 37252, '<td valign="top">Nice juxtaposition of the stormy clouds and the calm foreground waters.</td>', 'Nice juxtaposition of the stormy clouds and the calm foreground waters.', '2015-01-31 21:26:56.000000', NULL, 1),
