INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7308609, 1140311, 37252, '<td valign="top">I like where you were going with this, but feel the light is a bit too bright</td>', 'I like where you were going with this, but feel the light is a bit too bright', '2015-01-31 21:28:19.000000', NULL, 1),
(7308610, 1140310, 37252, '<td valign="top">The roof angle really makes this image nice</td>', 'The roof angle really makes this image nice', '2015-01-31 21:28:42.000000', NULL, 1),
(7308611, 1140223, 37252, '<td valign="top">Wonderful bokeh and sharp focus</td>', 'Wonderful bokeh and sharp focus', '2015-01-31 21:29:24.000000', NULL, 1),
(7308612, 1140366, 37252, '<td valign="top">good use of leading lines</td>', 'good use of leading lines', '2015-01-31 21:30:27.000000', NULL, 1),
(7308613, 1140262, 37252, '<td valign="top">I wish January in Michigan looked so inviting</td>', 'I wish January in Michigan looked so inviting', '2015-01-31 21:30:51.000000', NULL, 1),
(7308614, 1140313, 37252, '<td valign="top">I love nature, and this image is all about it. I do feel that maybe too much brown - maybe if the tree stump had some green moss on it to add color it would pop more. Still giving high marks as I do like this.</td>', 'I love nature, and this image is all about it. I do feel that maybe too much brown - maybe if the tree stump had some green moss on it to add color it would pop more. Still giving high marks as I do like this.', '2015-01-31 21:32:07.000000', NULL, 1),
(7308615, 1140367, 37252, '<td valign="top">Love love love this! Please let me know how you did this effect. Really would like to know if you would share</td>', 'Love love love this! Please let me know how you did this effect. Really would like to know if you would share', '2015-01-31 21:33:09.000000', NULL, 1),
(7308616, 1140365, 37252, '<td valign="top">perfect lighting to capture the steam.</td>', 'perfect lighting to capture the steam.', '2015-01-31 21:33:40.000000', NULL, 1),
(7308617, 1139992, 177322, '<td valign="top">I appreciate the geometric and freeform shapes incorporated within the square.  Well, and quickly, seen.</td>', 'I appreciate the geometric and freeform shapes incorporated within the square.  Well, and quickly, seen.', '2015-01-31 21:34:44.000000', NULL, 1),
(7308618, 1140363, 37252, '<td valign="top">cute kitty</td>', 'cute kitty', '2015-01-31 21:35:13.000000', NULL, 1),
(7308619, 1140228, 37252, '<td valign="top">really nice use of leading lines!</td>', 'really nice use of leading lines!', '2015-01-31 21:35:37.000000', NULL, 1),
(7308621, 1140328, 37252, '<td valign="top">I really enjoy the simplicity here and the sharp details.</td>', 'I really enjoy the simplicity here and the sharp details.', '2015-01-31 21:37:52.000000', NULL, 1),
(7308622, 1140342, 37252, '<td valign="top">pretty noisy and lack of focus distracts from the image for me.</td>', 'pretty noisy and lack of focus distracts from the image for me.', '2015-01-31 21:38:49.000000', NULL, 1),
(7308623, 1140344, 37252, '<td valign="top">Beautiful lighting and the details are exquisite</td>', 'Beautiful lighting and the details are exquisite', '2015-01-31 21:39:36.000000', NULL, 1),
(7308624, 1140263, 37252, '<td valign="top">ooooh, kitty has it''s dark side. lol Love it</td>', 'ooooh, kitty has it''s dark side. lol Love it', '2015-01-31 21:40:01.000000', NULL, 1),
(7308625, 1140387, 37252, '<td valign="top">I like the pose and that you captured it calling out. The highlights are blown out and that''s the only thing hurting this image.</td>', 'I like the pose and that you captured it calling out. The highlights are blown out and that''s the only thing hurting this image.', '2015-01-31 21:42:09.000000', NULL, 1),
(7308626, 1140222, 37252, '<td valign="top">interesting angle</td>', 'interesting angle', '2015-01-31 21:44:23.000000', NULL, 1),
(7308627, 1140225, 37252, '<td valign="top">B&amp;W suits this well. Nice sharp focus and details</td>', 'B&W suits this well. Nice sharp focus and details', '2015-01-31 21:46:24.000000', NULL, 1),
(7308629, 1140299, 37252, '<td valign="top">I do like this - the colors, the texture, the simplicity. I feel maybe the pumpkin is placed just a tad too close to the edge, but it really is a nice image.</td>', 'I do like this - the colors, the texture, the simplicity. I feel maybe the pumpkin is placed just a tad too close to the edge, but it really is a nice image.', '2015-01-31 21:48:05.000000', NULL, 1),
(7308631, 1140274, 37252, '<td valign="top">different and appealing. Nice colors</td>', 'different and appealing. Nice colors', '2015-01-31 21:50:11.000000', NULL, 1),
(7308633, 1140124, 37252, '<td valign="top">Nice DOF and focus</td>', 'Nice DOF and focus', '2015-01-31 21:51:27.000000', NULL, 1),
(7308635, 1140342, 177322, '<td valign="top">Clearly a candid, hand-held, night capture - technically difficult given those constraints; so there are, naturally, the inherent troubles present:  blurred, grainy, OOF.  Yet, I kept coming back to it. It was the last image of this challenge I scored because I struggled to balance its technical flaws against the poignancy of the image. <br/> <br/>Initially, it was the striking golden light slicing the square that drew my attention, so I thought the composition good for the square crop. But upon seeing what you were recording, you snagged my emotions - and held on. <br/> <br/>If I had to rate this strictly on technical criteria, I hope you understand it would not do well;  however, the emotional impact is nearly overwhelming and what you have captured deserves laudations.  Eight from me.</td>', 'Clearly a candid, hand-held, night capture - technically difficult given those constraints; so there are, naturally, the inherent troubles present:  blurred, grainy, OOF.  Yet, I kept coming back to it. It was the last image of this challenge I scored because I struggled to balance its technical flaws against the poignancy of the image.  Initially, it was the striking golden light slicing the square that drew my attention, so I thought the composition good for the square crop. But upon seeing what you were recording, you snagged my emotions - and held on.  If I had to rate this strictly on technical criteria, I hope you understand it would not do well;  however, the emotional impact is nearly overwhelming and what you have captured deserves laudations.  Eight from me.', '2015-01-31 21:52:43.000000', NULL, 1),
(7308637, 1140265, 37252, '<td valign="top">What a gorgeous girl. Nicely done with the lighting and focus.</td>', 'What a gorgeous girl. Nicely done with the lighting and focus.', '2015-01-31 21:54:53.000000', NULL, 1),
(7308638, 1140336, 37252, '<td valign="top">What an interesting find!</td>', 'What an interesting find!', '2015-01-31 21:55:48.000000', NULL, 1),
(7308671, 1140054, 37858, '<td valign="top">Nice smile and I like the way you''ve filled the frame.  I think the image would have benefited with a wider range of tonality rather than quite so much middle-gray.</td>', 'Nice smile and I like the way you''ve filled the frame.  I think the image would have benefited with a wider range of tonality rather than quite so much middle-gray.', '2015-02-01 00:06:53.000000', NULL, 1),
(7308680, 1140288, 37858, '<td valign="top">This is fine as far as it goes, but would benefit from some additional focal point of interest (a cat in the window, a person peeking between the lacy curtains, etc.).  The lines of the downspout balance the window nicely and the shadow fills between them well, too.</td>', 'This is fine as far as it goes, but would benefit from some additional focal point of interest (a cat in the window, a person peeking between the lacy curtains, etc.).  The lines of the downspout balance the window nicely and the shadow fills between them well, too.', '2015-02-01 00:10:06.000000', NULL, 1),
(7308687, 1140027, 37858, '<td valign="top">Good pattern and nice shades of green and yellow.  However, some added interesting focal point (maybe someone peeking through the blocks or, if that wouldn''t work, maybe a beam of light coming from behind the glass) might make the image more compelling.</td>', 'Good pattern and nice shades of green and yellow.  However, some added interesting focal point (maybe someone peeking through the blocks or, if that wouldn''t work, maybe a beam of light coming from behind the glass) might make the image more compelling.', '2015-02-01 00:12:44.000000', NULL, 1),
(7308696, 1140196, 37858, '<td valign="top">Might be my eyes, but it seems that the eagle''s head is a bit out of focus.  Other than that, I like the image.  I''m not usually a fan of such a heavy vignette, but in this instance it works well enough for me.  (Just my 2¢ worth.)</td>', 'Might be my eyes, but it seems that the eagle''s head is a bit out of focus.  Other than that, I like the image.  I''m not usually a fan of such a heavy vignette, but in this instance it works well enough for me.  (Just my 2¢ worth.)', '2015-02-01 00:21:12.000000', NULL, 1),
(7308702, 1140403, 37858, '<td valign="top">I''m not experienced with night flash, so I am merely asking rather than critiquing, but is the flash too bright for this image?  I like the idea and the composition.  Just not sure about the flash.</td>', 'I''m not experienced with night flash, so I am merely asking rather than critiquing, but is the flash too bright for this image?  I like the idea and the composition.  Just not sure about the flash.', '2015-02-01 00:24:01.000000', NULL, 1),
(7308706, 1140224, 37858, '<td valign="top">Seems to be a bit out of focus or, perhaps, just using an aperture that is narrower than the depth of the flower.</td>', 'Seems to be a bit out of focus or, perhaps, just using an aperture that is narrower than the depth of the flower.', '2015-02-01 00:26:28.000000', NULL, 1),
(7308712, 1140373, 37858, '<td valign="top">Beautiful model, great eyes.  I also like the flip of her hair and the soft, heavy collar framing her face.  I wish there was a wider tonal range, though.  The whole picture seems to be a bit flat because middle-gray tones predominate.  (Just my 2¢)</td>', 'Beautiful model, great eyes.  I also like the flip of her hair and the soft, heavy collar framing her face.  I wish there was a wider tonal range, though.  The whole picture seems to be a bit flat because middle-gray tones predominate.  (Just my 2¢)', '2015-02-01 00:30:32.000000', NULL, 1),
(7308713, 1140223, 37858, '<td valign="top">As my kids used to say, "Eeeeewww".</td>', 'As my kids used to say, "Eeeeewww".', '2015-02-01 00:32:07.000000', NULL, 1),
(7308716, 1140333, 37858, '<td valign="top">Nice.  I like it.  Good balance between the door on the left and the shaddow on the right.  Love the warm orange color, which is perfect with all the grays.  One of my favorites so far.</td>', 'Nice.  I like it.  Good balance between the door on the left and the shaddow on the right.  Love the warm orange color, which is perfect with all the grays.  One of my favorites so far.', '2015-02-01 00:33:32.000000', NULL, 1),
(7308719, 1140310, 37858, '<td valign="top">Nice framing.</td>', 'Nice framing.', '2015-02-01 00:34:08.000000', NULL, 1),
(7308720, 1140312, 37858, '<td valign="top">Interesting crop and a photo that takes a moment to appreciate.  Well done.</td>', 'Interesting crop and a photo that takes a moment to appreciate.  Well done.', '2015-02-01 00:36:10.000000', NULL, 1),
(7308723, 1140158, 37858, '<td valign="top">Interesting minimalist presentation.  I like it.</td>', 'Interesting minimalist presentation.  I like it.', '2015-02-01 00:37:34.000000', NULL, 1),
(7308729, 1139937, 37858, '<td valign="top">I really appreciate the "set up" in this image.  Well done.  I scored this a 7 on the first go round (May increase it after I''ve seen the rest of the photographs).  Having said that, if you had used a Red Sox hat I would have added a bonus and scored this a 10.  However, out of respect for the rivalry I didn''t take any points off for using the wrong hat.</td>', 'I really appreciate the "set up" in this image.  Well done.  I scored this a 7 on the first go round (May increase it after I''ve seen the rest of the photographs).  Having said that, if you had used a Red Sox hat I would have added a bonus and scored this a 10.  However, out of respect for the rivalry I didn''t take any points off for using the wrong hat.', '2015-02-01 00:42:34.000000', NULL, 1),
